// screens/DetailScreen.js

import React, { useState } from 'react';
import {
  ScrollView,
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  Dimensions
} from 'react-native';
import axios from 'axios';
import {
  VictoryChart,
  VictoryLine,
  VictoryTheme,
  VictoryAxis
} from 'victory-native';

export default function DetailScreen({ route }) {
  const { sensor, apiUrl } = route.params;
  const [history, setHistory] = useState(sensor.history || []);

  const fetchHistory = async () => {
    try {
      const response = await axios.get(`${apiUrl}/sensors/${sensor.id}`);
      setHistory(response.data.history);
    } catch (error) {
      console.error(error);
    }
  };

  return (
    <ScrollView style={styles.screen} contentContainerStyle={{ padding: 16 }}>
      <View style={styles.card}>
        <Text style={styles.title}>Histórico de {sensor.name}</Text>
        <View style={styles.chartContainer}>
          <VictoryChart
            theme={VictoryTheme.material}
            domainPadding={20}
            width={Dimensions.get('window').width - 64}
            height={200}
          >
            <VictoryAxis tickFormat={(t) => `#${t}`} />
            <VictoryAxis dependentAxis />
            <VictoryLine
              animate={{ duration: 500 }}
              data={history.map((v, i) => ({ x: i + 1, y: v }))}
              style={{
                data: { stroke: '#007AFF' }
              }}
            />
          </VictoryChart>
        </View>
      </View>

      <TouchableOpacity style={styles.button} onPress={fetchHistory}>
        <Text style={styles.buttonText}>ATUALIZAR</Text>
      </TouchableOpacity>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  screen: {
    flex: 1,
    backgroundColor: '#f2f2f7'
  },
  card: {
    backgroundColor: '#fff',
    borderRadius: 8,
    padding: 16,
    marginBottom: 24,
    // sombra iOS
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 1 },
    shadowOpacity: 0.1,
    shadowRadius: 2,
    // elevação Android
    elevation: 2
  },
  title: {
    fontSize: 18,
    fontWeight: '600',
    marginBottom: 12
  },
  chartContainer: {
    alignItems: 'center'
  },
  button: {
    backgroundColor: '#007AFF',
    borderRadius: 8,
    paddingVertical: 14,
    alignItems: 'center',
    marginHorizontal: 16
  },
  buttonText: {
    color: '#fff',
    fontWeight: '600'
  }
});
